    rem=obs.get('progress',{}).get('remaining',5)
    def stop(msg):
        global phase,woke
        phase='stop'
        if not woke:
            woke=True;wake(msg)
    if tc>lt:
        lt=tc
        if phase!='pull': stop('touched again, stopped')
    if phase=='rev' and abs(h)>45: stop('hitch too big, stopped')
