import math
L1=3.9; L2=10.2
st={'X':0.,'Y':0.,'yaw':0.,'corners':[],'phase':'REV','fwd_t':0.,'e_f':0.,'lastp':-10.,'walls_w':[],'werr':0,'stopwake':0}

def vf2w(x,y):
    c=math.cos(st['yaw']); s=math.sin(st['yaw'])
    return (st['X']+x*c-y*s, st['Y']+x*s+y*c)

def w2vf(X,Y):
    dx=X-st['X']; dy=Y-st['Y']; c=math.cos(st['yaw']); s=math.sin(st['yaw'])
    return (dx*c+dy*s, -dx*s+dy*c)

def pts(view,key):
    out=[]
    try:
        o=view.get('origin',[0,0])
        for p in view.get(key) or []:
            try:
                b=math.radians(float(p[0])); d=float(p[1])
                out.append((o[0]+d*math.cos(b), o[1]+d*math.sin(b)))
            except Exception:
                pass
    except Exception:
        pass
    return out

def raydist(tw,phi,tube):
    c=math.cos(phi); s=math.sin(phi); d=15.0
    for (u,w) in tw:
        a=u*c+w*s
        if a>0 and a<d and abs(-u*s+w*c)<tube:
            d=a
    return d

def bay_info(R):
    cs=sorted(st['corners'],key=lambda c:-c[2])[:4]
    if len(cs)<2: return None
    P=[w2vf(c[0],c[1]) for c in cs]
    best=None
    for i in range(len(P)):
        for j in range(i+1,len(P)):
            d=math.hypot(P[i][0]-P[j][0],P[i][1]-P[j][1])
            if 2.3<=d<=5.5:
                mid=((P[i][0]+P[j][0])/2,(P[i][1]+P[j][1])/2)
                dr=math.hypot(mid[0]-R[0],mid[1]-R[1])
                if best is None or dr<best[0]:
                    best=(dr,mid,(P[j][0]-P[i][0])/d,(P[j][1]-P[i][1])/d)
    if best is None: return None
    dr,mid,ex,ey=best
    ax,ay=-ey,ex
    if len(P)>=3:
        cx=sum(p[0] for p in P)/len(P); cy=sum(p[1] for p in P)/len(P)
        if (cx-mid[0])*ax+(cy-mid[1])*ay<0: ax,ay=-ax,-ay
    else:
        if (mid[0]-R[0])*ax+(mid[1]-R[1])*ay<0: ax,ay=-ax,-ay
    return mid,(ax,ay),dr

def control(obs):
    try:
        return _control(obs)
    except Exception as ex:
        if st['werr']==0:
