                    best=(dr,mid,(P[j][0]-P[i][0])/d,(P[j][1]-P[i][1])/d)
    if best is None: return None
    dr,mid,ex,ey=best
    ax,ay=-ey,ex
    if len(P)>=3:
        cx=sum(p[0] for p in P)/len(P); cy=sum(p[1] for p in P)/len(P)
        if (cx-mid[0])*ax+(cy-mid[1])*ay<0: ax,ay=-ax,-ay
    else:
        if (mid[0]-R[0])*ax+(mid[1]-R[1])*ay<0: ax,ay=-ax,-ay
    return mid,(ax,ay),dr

def control(obs):
    try:
        return _control(obs)
    except Exception as ex:
        if st['werr']==0:
            st['werr']=1
            wake('controller exception: %r'%(ex,))
        return (0.0,0.0,-41.0)

def _control(obs):
    t=obs.get('t',0.); dt=obs.get('dt',0.1) or 0.1
    mo=obs['motion']; v=mo.get('v_mps',0.); sd=obs.get('steer_deg',0.)
    ds=v*dt
    st['yaw']+=ds*math.tan(math.radians(sd))/L1
    st['X']+=ds*math.cos(st['yaw']); st['Y']+=ds*math.sin(st['yaw'])
    rig=obs['rig']; h=obs['hitch_deg']
    look=rig.get('screen_gaze_deg')
    if look is None: look=-41.0
    views=obs.get('views') or {}
    walls=[]; corners=[]
    for k,vw in views.items():
        walls+=pts(vw,'walls')
        corners+=pts(vw,'target_corners')
    if views:
        st['walls_w']=[vf2w(x,y) for (x,y) in walls]
    else:
        walls=[w2vf(X,Y) for (X,Y) in st['walls_w']]
    for (x,y) in corners:
        X,Y=vf2w(x,y); m=False
        for c in st['corners']:
            if math.hypot(c[0]-X,c[1]-Y)<1.8:
                n=c[2]; c[0]=(c[0]*n+X)/(n+1); c[1]=(c[1]*n+Y)/(n+1); c[2]=min(n+1,50); m=True; break
        if not m: st['corners'].append([X,Y,1])
    R=rig['trailer_rear']; th=math.radians(rig['trailer_heading_deg'])
    bx,by=-math.cos(th),-math.sin(th); lx,ly=math.sin(th),-math.cos(th)
    tw=[]
    for (x,y) in walls:
        dx=x-R[0]; dy=y-R[1]
        u=dx*bx+dy*by; w=dx*lx+dy*ly
        if -0.5<u<16: tw.append((u,w))
    tube=1.75
    angs=[math.radians(i*2) for i in range(-30,31)]
    ds_=[raydist(tw,a,tube) for a in angs]
    dmax=max(ds_); thr=dmax-0.7
    groups=[]; cur=[]
    for i,d in enumerate(ds_):
        if d>=thr: cur.append(i)
        elif cur: groups.append(cur); cur=[]
    if cur: groups.append(cur)
    g0=None
    for g in groups:
        if 30 in g or min(abs(i-30) for i in g)<=3: g0=g
    if g0 is None: g0=max(groups,key=len)
    e_gap=sum(angs[i] for i in g0)/len(g0)
    e=e_gap; mode='gap'
    bi=bay_info(R)
    if bi is not None:
        mid,(ax,ay),dr=bi
        if dr<25:
            s=(R[0]-mid[0])*ax+(R[1]-mid[1])*ay
            Ld=8.0
            Px=mid[0]+ax*(s+Ld); Py=mid[1]+ay*(s+Ld)
            dx=Px-R[0]; dy=Py-R[1]
            u=dx*bx+dy*by; w=dx*lx+dy*ly
            eb=math.atan2(w,u)
            if abs(eb)<math.radians(70):
                need=min(math.hypot(dx,dy),8.0)
                if raydist(tw,eb,1.5)>=need-0.5 or dr<3:
                    e=eb; mode='bay'
    st['e_f']+=0.35*(e-st['e_f'])
    ef=st['e_f']
    hdes=-math.degrees(math.atan2(2*L2*math.sin(ef),10.0))
    hdes=max(-45.,min(45.,hdes))
    rem=obs.get('progress',{}).get('remaining',99.)
    status=obs.get('status','')
    if st['phase']=='REV' and (abs(h)>62 or status=='JACKKNIFED'):
        st['phase']='FWD'; st['fwd_t']=t
    if st['phase']=='FWD':
        if abs(h)<20 or t-st['fwd_t']>12:
            st['phase']='REV'
        else:
            steer=-25.0 if h>0 else 25.0
            return (steer,1.0,look)
    steer=-math.degrees(math.atan(L1/L2*math.sin(math.radians(hdes))))+1.2*(h-hdes)
    steer=max(-42.,min(42.,steer))
    spd=1.4
    if abs(h-hdes)>12: spd=0.9
    if ds_[30]<5: spd=min(spd,0.7)
    if rem<10: spd=min(spd,0.7)
    if rem<4: spd=min(spd,0.5)
    if ds_[30]<0.8 and dmax<1.5:
        spd=0.0
        if st['stopwake']==0:
            st['stopwake']=1; wake('blocked behind trailer, stopping')
    if t-st['lastp']>=2.0:
        st['lastp']=t
        print('t%.0f h%.0f hd%.0f st%.0f v%.1f e%.0f dmax%.1f d0%.1f %s rem%.1f nc%d'%(t,h,hdes,steer,v,math.degrees(ef),dmax,ds_[30],mode,rem,len(st['corners'])))
    return (steer,-spd,look)

