def _c(obs):
    t=obs['t']; dt=obs.get('dt',0.1) or 0.1
    v=obs['motion']['v_mps']; sd=obs.get('steer_deg',0.)
    ds=v*dt
    st['yaw']+=ds*math.tan(math.radians(sd))/L1
    if v<0: st['d']+=-ds
    h=obs['hitch_deg']
    th=math.degrees(st['yaw'])+obs['rig']['trailer_heading_deg']
    if st['tgt'] is None: st['tgt']=th+2.0
    err=st['tgt']-th
    hdes=max(-15.,min(15.,-2.5*err))
    steer=-math.degrees(math.atan(L1/L2*math.sin(math.radians(hdes))))+1.2*(h-hdes)
    steer=max(-42.,min(42.,steer))
    rem=obs.get('progress',{}).get('remaining',99.)
    if t-st['lp']>=1.0:
        st['lp']=t
        print('t%.1f h%.1f hd%.1f th%.1f err%.1f st%.0f v%.2f d%.1f rem%.1f %s'%(t,h,hdes,th,err,steer,v,st['d'],rem,obs['status']))
    if st['stop'] or st['d']>11 or abs(h)>30:
        if not st['stop']:
            st['stop']=1; wake('stopping: d=%.1f h=%.1f rem=%.1f'%(st['d'],h,rem))
        return (0.0,0.0,-41.0)
    spd=0.7 if rem>3 else 0.5
    return (steer,-spd,-41.0)

